def icon(n):return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[n]+'</svg>'
def card(p, catalogue=False):
 caption='<span class="photo-caption">Reference image</span>' if p.get('imageKind')=='representative' else ''
 photo=(f'<img src="{e(p["image"])}" referrerpolicy="no-referrer" alt="" loading="lazy" width="420" height="320">' if p['image'] else '<div class="photo-request"><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="10" y="16" width="44" height="34" rx="5"/><path d="m10 40 13-12 11 10 7-6 13 12"/><circle cx="41" cy="26" r="4"/></svg><span>Product photograph<br>available on enquiry</span></div>')
 auxiliary=f'''<div class="card-aux-row"><label class="compare-check"><input type="checkbox" data-compare="{p['id']}"> Compare</label><button type="button" class="quickview-btn" data-quickview="{p['id']}">Quick view</button></div>''' if catalogue else ''
 return f'''<article class="product-card" data-product="{p['id']}"><div class="product-visual"><a href="product.html?id={p['id']}" tabindex="-1" aria-hidden="true">{photo}</a>{caption}<button class="save-button" data-save="{p['id']}" aria-label="Save {e(p['name'])}" aria-pressed="false">{icon('heart')}</button></div><div class="product-info"><span class="micro-label">{e(p['subcategory'])}</span><h3><a href="product.html?id={p['id']}">{e(p['name'])}</a></h3><p>{e(p['features'][0])}</p><div class="product-bottom"><span>Price coming soon</span><button class="add-button" data-add="{p['id']}" aria-label="Add {e(p['name'])} to cart">Add to cart</button></div>{auxiliary}</div></article>'''
def catcard(c):
 count=sum(p['category']==c['id'] for p in products)
 image=f'<img src="{e(c["image"])}" referrerpolicy="no-referrer" alt="" loading="lazy" width="420" height="320">' if c['image'] else f'<span class="category-icon">{icon(c["icon"])}</span>'
 blurbs={'furniture':'Beds, stretchers & more','equipment':'Monitors, ventilators & more','instruments':'Forceps, scissors & more','mgps':'OT setups, panels & more','linen':'OT drapes, gowns & more','consumables':'Gloves, masks, drapes & more'}
 return f'''<a class="category-card" href="products.html?category={c['id']}"><div class="category-visual">{image}</div><span class="category-mark">{icon(c['icon'])}</span><h3>{e(c['name'])}</h3><span class="category-description">{blurbs.get(c['id'],e(c['description']))}</span><span class="category-meta"><span>{str(count)+' selected products' if count else 'Enquire by specialty'}</span><span class="category-arrow">{icon('arrow')}</span></span></a>'''
def brand():
 return '<a class="brand" href="index.html" aria-label="Surgical Wholesale Mart Private Limited home"><span class="brand-emblem" aria-hidden="true"><img src="assets/brand-logo.png" alt="" width="795" height="746"></span><span class="brand-divider" aria-hidden="true"></span><span class="brand-wordmark"><strong>Surgical <span class="brand-orange">Wholesale</span> Mart</strong> <span class="brand-legal">Pvt. Ltd.</span></span></a>'
def header(page):
 nav=(ROOT/'data/header-nav.html').read_text().strip()
 active='products.html' if page=='product.html' else page
 nav=nav.replace(f'href="{active}"',f'href="{active}" aria-current="page"')
 return f'<a class="skip-link" href="#main">Skip to content</a><header class="store-header"><div class="header-main">{brand()}</div>{nav}</header>'

def footer(home=False):
 template='home-footer.html' if home else 'shared-footer.html'
 return (ROOT/'data'/template).read_text(encoding='utf-8')+'<div class="toast" role="status" aria-live="polite"></div>'
def mobile_navigation(filename):
 page=filename.removesuffix('.html')
 active={'product':'products','checkout':'cart'}.get(page,page)
 nav=(ROOT/'data/mobile-footer-nav.html').read_text(encoding='utf-8')
 for tab in ('index','products','search','cart','contact'):
  nav=nav.replace('{{'+tab+'}}',' class="is-active" aria-current="page"' if tab==active else '')
 return (ROOT/'data/mobile-navigation-skeleton.html').read_text(encoding='utf-8')+nav

